// ---- inline **bold** / *italic* parser ----
function runs(text, size = 19, extra = {}) {
  const out = [];
  for (const part of text.split(/(\*\*[^*]+\*\*)/g)) {
    if (!part) continue;
    if (/^\*\*[^*]+\*\*$/.test(part))
      out.push(new TextRun({ text: part.slice(2, -2), bold: true, font: FONT, size, ...extra }));
    else
      for (const it of part.split(/(\*[^*]+\*)/g)) {
        if (!it) continue;
        if (/^\*[^*]+\*$/.test(it))
          out.push(new TextRun({ text: it.slice(1, -1), italics: true, font: FONT, size, ...extra }));
        else out.push(new TextRun({ text: it, font: FONT, size, ...extra }));
      }
  }
  return out;
}
// ---- math DSL: _(sub) ^(sup) ~italic~ , rest roman ----
function mathRuns(s, size = 18) {
  const out = []; let i = 0, buf = "";
  const push = (txt, m) => { if (!txt) return; const o = { font: FONT, size };
    if (m === "sub") o.subScript = true; if (m === "sup") o.superScript = true;
    if (m === "it") o.italics = true; out.push(new TextRun({ text: txt, ...o })); };
  while (i < s.length) {
    const c = s[i];
    if (c === "_" && s[i + 1] === "(") { push(buf, "r"); buf = ""; i += 2; let d = "";
      while (s[i] !== ")" && i < s.length) d += s[i++]; i++; push(d, "sub"); }
    else if (c === "^" && s[i + 1] === "(") { push(buf, "r"); buf = ""; i += 2; let d = "";
      while (s[i] !== ")" && i < s.length) d += s[i++]; i++; push(d, "sup"); }
    else if (c === "~") { push(buf, "r"); buf = ""; i++; let d = "";
      while (s[i] !== "~" && i < s.length) d += s[i++]; i++; push(d, "it"); }
    else { buf += c; i++; }
  }
  push(buf, "r");
  return out;
}
