// ---- booktabs table ----
function table(colW, rows) {
  const border = { top: { style: BorderStyle.SINGLE, size: 12, color: DARK },
    bottom: { style: BorderStyle.SINGLE, size: 12, color: DARK },
    left: NONE, right: NONE, insideHorizontal: NONE, insideVertical: NONE };
  const trs = rows.map((cells, ri) => new TableRow({ tableHeader: ri === 0,
    children: cells.map((txt, ci) => new TableCell({
      width: { size: colW[ci], type: WidthType.DXA },
      shading: ri === 0 ? { type: ShadingType.CLEAR, fill: HEADSH } : undefined,
      borders: ri === 0 ? { bottom: { style: BorderStyle.SINGLE, size: 8, color: DARK } } : undefined,
      margins: { top: 40, bottom: 40, left: 80, right: 80 },
      children: [new Paragraph({ alignment: ci === 0 ? AlignmentType.LEFT : AlignmentType.CENTER,
        spacing: { line: 220, after: 0 }, children: runs(txt, 16, ri === 0 ? { bold: true } : {}) })],
    })) }));
  return new Table({ columnWidths: colW, width: { size: TW, type: WidthType.DXA }, borders: border, rows: trs });
}
