col(H1("4. Модели"));
col(P("**GEDS (SEIRS-Bullwhip-Hysteresis)** — авторский движок: каждый узел проходит состояния Susceptible → Exposed (буфер запасов поглощает дефицит) → Infected (потеря выпуска с нелинейным усилением) → Recovered (гистерезис). **Бейслайны** (ноль подгоняемых параметров): межотраслевая модель Леонтьева, линейная сетевая диффузия, наивный предиктор среднего. Конфигурация детерминирована (stochastic_sigma = 0, seed = 0) и запинена golden-тестом."));
col(H2("4.1. Формальная спецификация движка"));
col(P("Пусть s_i(t) ∈ [0, 1] — уровень шока узла i на неделе t; D_eff — матрица эффективных зависимостей. Обновление за шаг (векторизовано по узлам). Входящее давление с эффектом хлыста, где β_i = bullwhip-фактор (1,25 в состоянии E):"));
col(EQ(1, "in_(i)(t) = ~β~_(i) · Σ_(j) D_(eff)[i,j] · s_(j)(t)"));
col(P("Импульс воздействия (δ — propagation_decay, V — уязвимость, A — нелинейное усиление, ρ — устойчивость, множитель (1−s) даёт насыщение):"));
col(EQ(2, "Δ_(i)(t) = ~δ~ · in_(i)(t) · V_(i) · A_(i) · (1−~ρ~_(i)) · (1−s_(i)(t))"));
col(P("Недельная скорость восстановления, привязанная к узловой задержке delay_i (8 недель — опорная):"));
col(EQ(3, "~γ~_(i) = clip( recovery_rate · (8 / max(delay_(i), 0,5)), 0, 0,95 )"));
col(P("Переход состояния, где x_i — внешнее форсирование события (форма step/linear/exp/ramp), r_i = γ_i·s_i для незафорсированных узлов, ε — шум (в бенчмарке ε ≡ 0):"));
col(EQ(4, "s_(i)(t+1) = clip( max( x_(i)(t+1), s_(i)(t) + Δ_(i)(t) − r_(i)(t) + ~ε~_(i)(t) ), 0, 1 )"));
col(P("Наблюдаемая потеря выпуска узла (η — эластичность, f_i — пол гистерезиса R-состояния, ≥ 0,30 пока узел восстанавливается):"));
col(EQ(5, "L_(i)(t) = max( s_(i)(t) · ~η~_(i) · (1−~ρ~_(i)), f_(i)(t) )"));
col(P("Скалярный индекс тяжести каскада (c_i — центральность узла, d_i — входная экспозиция):"));
col(EQ(6, "CSI(t) = (1/N) · Σ_(i) s_(i)(t) · c_(i) · d_(i)"));
col(P("**Состояния SEIRS.** Узел из S переходит в E при пересечении входящим давлением триггера (буфер запасов глубиной inventory_scale поглощает дефицит), из E — в I, из I — в R при спаде шока; в R держится delay_i недель с полом выпуска f_i, затем возвращается в S — это и есть гистерезис. **Пять калибруемых параметров** θ = (amplification_mu, bullwhip_factor, recovery_rate, inventory_scale, distress_base); остальные величины структурны либо фиксированы. Бейслайны формально: Леонтьев решает (I−A)^{-1}-подобное равновесие потерь; линейная диффузия итерирует s(t+1)=s(t)+δ·(W·s(t)) без насыщения и восстановления; наивный предиктор возвращает среднее выборки."));

