const pageProps = { page: { size: { width: 11906, height: 16838 },
  margin: { top: 1134, bottom: 1134, left: 1134, right: 1134 } } };
const footer = () => new Footer({ children: [new Paragraph({
  border: { top: { style: BorderStyle.SINGLE, size: 6, color: GREEN, space: 6 } },
  tabStops: [{ type: TabStopType.RIGHT, position: TW }],
  children: [new TextRun({ text: "GEDS — рабочий препринт", italics: true, font: FONT, size: 14, color: GREY }),
    new TextRun({ children: ["\t", PageNumber.CURRENT, " из ", PageNumber.TOTAL_PAGES], font: FONT, size: 14, color: GREY })] })] });

const sections = [{ properties: { ...pageProps, column: { count: 1 }, footers: { default: footer() } }, children: front }];
let buf = [];
const flushCol = () => { if (buf.length) { sections.push({ properties: { ...pageProps, type: SectionType.CONTINUOUS,
  column: { count: 2, space: 454, equalWidth: true }, footers: { default: footer() } }, children: buf }); buf = []; } };
for (const item of flow) {
  if (item.full) { flushCol();
    sections.push({ properties: { ...pageProps, type: SectionType.CONTINUOUS, column: { count: 1 }, footers: { default: footer() } }, children: item.children }); }
  else buf.push(item.el);
}
flushCol();

const doc = new Document({ creator: "GEDS", title: "GEDS — трёхосевая валидация (препринт)",
  styles: { default: { document: { run: { font: FONT, size: 19, color: DARK }, paragraph: { spacing: { line: 240 } } } } },
  sections });
Packer.toBuffer(doc).then((b) => { fs.writeFileSync(OUT, b); console.log("wrote", OUT, b.length, "bytes"); });
